/**
 * Generates `src/archives/seven-zip-wasm.ts` with the 7-Zip WASM binary from
 * `node_modules/7z-wasm/7zz.wasm` as a base64 string. The generated file is
 * committed so `tsc` always works standalone; run this script whenever
 * `7z-wasm` is upgraded.
 *
 * Embedding the bytes in the package (instead of loading `7zz.wasm` as a side
 * asset) means no runtime fetch of the wasm file is ever needed: bundlers
 * (Vite/Rollup/webpack) and dev servers neither rewrite nor serve it, so the
 * Emscripten loader cannot fail with "both async and sync fetching of the wasm
 * failed". See `configureArchiveWasm` for consumers who still prefer an
 * external asset.
 */
import { createRequire } from 'node:module'
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const require = createRequire(import.meta.url)
const wasmPath = require.resolve('7z-wasm/package.json')
const wasmFile = join(dirname(wasmPath), '7zz.wasm')

const header = `/**
 * Generated by \`scripts/generate-7zz-wasm.mjs\` — DO NOT EDIT.
 * Base64 of \`7z-wasm\`'s \`7zz.wasm\` (7-Zip 24.09, ~1.6 MB). Kept as the only
 * source of the wasm bytes so archive extraction never depends on a runtime
 * asset fetch.
 */
export const SEVEN_ZIP_WASM_BASE64 = '`

const base64 = readFileSync(wasmFile).toString('base64')
const outFile = join(here, '..', 'src', 'archives', 'seven-zip-wasm.ts')
writeFileSync(outFile, `${header}${base64}'\n`)
console.log(`generated ${outFile} (${base64.length.toLocaleString()} base64 chars)`)